const dataArr = resp.data || [];
if (!dataArr.length || !Array.isArray(dataArr[0].embedding)) {
  return [{ json: { _error: { status: 502, body: { error: 'bad_embedding_response', code: 'upstream_error', raw: resp } } } }];
}

