  vec = dataArr[0].embedding;
} else {
  const len = dataArr[0].embedding.length;
  vec = new Array(len).fill(0);
  for (const item of dataArr) {
    for (let i = 0; i < len; i++) vec[i] += item.embedding[i];
  }
  const n = dataArr.length;
  vec = vec.map(v => v / n);
}

